/* @lc app=leetcode id=3428 lang=kotlin */ class Solution { fun minMaxSums(nums: IntArray, k: Int): Int = 1_000_000_007L.let { M -> nums.sorted().let { a -> a.size.let { n -> (1..n).runningFold(1L) { x, i -> x * i % M }.let { fact -> LongArray(n + 1).also { t -> t[n] = java.math.BigInteger.valueOf(fact[n]).modInverse(java.math.BigInteger.valueOf(M)).toLong() }.also { t -> (n downTo 1).forEach { i -> t[i - 1] = t[i] * i % M } }.let { ifact -> a.indices.fold(0L) { acc, i -> (acc + a[i].toLong() % M * ((0 until k).sumOf { j -> (if (j <= i) fact[i] * ifact[j] % M * ifact[i - j] % M else 0L) + (if (j <= n - 1 - i) fact[n - 1 - i] * ifact[j] % M * ifact[n - 1 - i - j] % M else 0L) } % M)) % M }.toInt() } } } } } }